import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.Dp3tugkT.js";const p=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),o={name:"09-interview-qa.md"};function n(s,e,l,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="category-1-system-design-redirection-mechanics" tabindex="-1">Category 1: System Design &amp; Redirection Mechanics <a class="header-anchor" href="#category-1-system-design-redirection-mechanics" aria-label="Permalink to &quot;Category 1: System Design &amp; Redirection Mechanics&quot;">​</a></h2><ol><li><strong>Why use HTTP 302 instead of HTTP 301 for a URL shortener?</strong><ul><li>HTTP 301 is permanently cached by client browsers. Once a user visits the link, subsequent visits bypass our server entirely. HTTP 302 ensures every click reaches our server, enabling 100% accurate click analytics.</li></ul></li><li><strong>How does Nanoid prevent collisions?</strong><ul><li>It utilizes the Node.js crypto API to generate cryptographically strong pseudorandom bytes. With a 64-character alphabet across 7 characters, there are over 4.3 trillion permutations, meaning billions of URLs can be generated with virtually zero collision probability.</li></ul></li><li><strong>What is the difference between Base62 encoding and Nanoid?</strong><ul><li>Base62 typically encodes a sequential auto-incrementing integer from a database. While compact, sequential IDs reveal total business volume to competitors and are vulnerable to sequential enumeration attacks. Nanoid generates random, non-sequential slugs with uniform entropy.</li></ul></li></ol><h2 id="category-2-database-concurrency" tabindex="-1">Category 2: Database &amp; Concurrency <a class="header-anchor" href="#category-2-database-concurrency" aria-label="Permalink to &quot;Category 2: Database &amp; Concurrency&quot;">​</a></h2><ol start="4"><li><strong>How do you handle click count updates under heavy concurrent traffic?</strong><ul><li>By using MongoDB&#39;s atomic <code>$inc</code> operator in <code>findOneAndUpdate</code>. Because <code>$inc</code> is an atomic field-level update, multiple concurrent requests increment the value safely without read-modify-write race conditions.</li></ul></li><li><strong>How would you scale this system to 100 million redirects per day?</strong><ul><li>100 million redirects per day is approximately 1,150 QPS average, with peaks around 5,000 QPS. I would introduce a Redis cache layer in front of MongoDB for hot slugs. Redirections would hit Redis with sub-millisecond latency, and click events would be queued via Kafka to update MongoDB in batches.</li></ul></li></ol><h2 id="category-3-architecture-frontend" tabindex="-1">Category 3: Architecture &amp; Frontend <a class="header-anchor" href="#category-3-architecture-frontend" aria-label="Permalink to &quot;Category 3: Architecture &amp; Frontend&quot;">​</a></h2><ol start="6"><li><strong>Why did you separate Redux Toolkit and TanStack Query on the frontend?</strong><ul><li>Redux Toolkit is optimized for synchronous client-side UI state (like auth status and active modal dialogues). TanStack Query is purpose-built for asynchronous server state, providing automatic caching, background refetching, and query invalidation out of the box.</li></ul></li></ol>',7)])])}const y=a(o,[["render",n]]);export{p as __pageData,y as default};
